    String? bn,
    String? mr,
    String? te,
    String? ta,
    String? gu,
    String? ml,
    String? or,
    String? pa,
  }) => switch (lang) {
    Lang.en => en,
    Lang.kn => kn,
    Lang.hi => hi ?? en,
    Lang.bn => bn ?? en,
    Lang.mr => mr ?? en,
    Lang.te => te ?? en,
    Lang.ta => ta ?? en,
