  String get ppfNote => _t(
    'Assumes the deposit is made by 5 April every year.',
    'ಪ್ರತಿ ವರ್ಷ ಏಪ್ರಿಲ್ 5ರೊಳಗೆ ಠೇವಣಿ ಮಾಡಲಾಗುತ್ತದೆ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ.',
    hi: 'मान लिया गया है कि जमा हर वर्ष 5 अप्रैल तक किया जाता है।',
    bn: 'ধরে নেওয়া হয়েছে প্রতি বছর 5 এপ্রিলের মধ্যে জমা করা হয়।',
    mr: 'दरवर्षी 5 एप्रिलपर्यंत ठेव भरली जाते असे गृहीत धरले आहे.',
    te: 'ప్రతి సంవత్సరం ఏప్రిల్ 5 లోపు డిపాజిట్ చేస్తారని భావించబడింది.',
    ta: 'ஒவ்வொரு ஆண்டும் ஏப்ரல் 5-க்குள் வைப்பு செலுத்தப்படும் எனக் கொள்ளப்படுகிறது.',
    gu: 'દર વર્ષે 5 એપ્રિલ સુધીમાં જમા થાય છે એમ માની લીધું છે.',
    ml: 'എല്ലാ വർഷവും ഏപ്രിൽ 5-നകം നിക്ഷേപിക്കുന്നു എന്ന് കണക്കാക്കുന്നു.',
    or: 'ପ୍ରତି ବର୍ଷ 5 ଏପ୍ରିଲ ସୁଦ୍ଧା ଜମା କରାଯାଏ ବୋଲି ଧରାଯାଇଛି।',
    pa: 'ਮੰਨਿਆ ਗਿਆ ਹੈ ਕਿ ਹਰ ਸਾਲ 5 ਅਪ੍ਰੈਲ ਤੱਕ ਜਮ੍ਹਾਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।',
  );
  String get rdNote => _t(
    'Assumes every instalment is paid on time.',
    'ಎಲ್ಲಾ ಕಂತುಗಳನ್ನು ಸಮಯಕ್ಕೆ ಪಾವತಿಸಲಾಗುತ್ತದೆ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ.',
    hi: 'मान लिया गया है कि हर किस्त समय पर जमा होती है।',
    bn: 'ধরে নেওয়া হয়েছে প্রতিটি কিস্তি সময়মতো দেওয়া হয়।',
