    gu: 'દરેક હપ્તો સમયસર ભરાય છે એમ માની લીધું છે.',
    ml: 'എല്ലാ തവണയും കൃത്യസമയത്ത് അടയ്ക്കുന്നു എന്ന് കണക്കാക്കുന്നു.',
    or: 'ପ୍ରତ୍ୟେକ କିସ୍ତି ଠିକ ସମୟରେ ଦିଆଯାଏ ବୋଲି ଧରାଯାଇଛି।',
    pa: 'ਮੰਨਿਆ ਗਿਆ ਹੈ ਕਿ ਹਰ ਕਿਸ਼ਤ ਸਮੇਂ ਸਿਰ ਭਰੀ ਜਾਂਦੀ ਹੈ।',
