      hi: 'राशि ₹${s.multipleOf} के गुणकों में होनी चाहिए।',
      bn: 'পরিমাণ ₹${s.multipleOf}-এর গুণিতকে হতে হবে।',
      mr: 'रक्कम ₹${s.multipleOf} च्या पटीत असावी.',
