    ),
    Issue.msscClosed => _t(
      'MSSC took deposits only until 31-03-2025. Use it for existing accounts.',
      'MSSC ಠೇವಣಿ 31-03-2025ರವರೆಗೆ ಮಾತ್ರ. ಈಗಿರುವ ಖಾತೆಗಳಿಗೆ ಮಾತ್ರ ಬಳಸಿ.',
      hi: 'MSSC में जमा केवल 31-03-2025 तक लिया गया। इसे मौजूदा खातों के लिए उपयोग करें।',
      bn: 'MSSC-তে জমা নেওয়া হত শুধু 31-03-2025 পর্যন্ত। পুরোনো অ্যাকাউন্টের জন্য ব্যবহার করুন।',
      mr: 'MSSC मध्ये 31-03-2025 पर्यंतच ठेवी घेतल्या. सध्याच्या खात्यांसाठी वापरा.',
      te: 'MSSC లో 31-03-2025 వరకు మాత్రమే డిపాజిట్లు స్వీకరించారు. ఉన్న ఖాతాలకు మాత్రమే ఉపయోగించండి.',
      ta: 'MSSC 31-03-2025 வரை மட்டுமே வைப்புகளை ஏற்றது. ஏற்கனவே உள்ள கணக்குகளுக்குப் பயன்படுத்தவும்.',
      gu: 'MSSC માં 31-03-2025 સુધી જ જમા લેવાતી હતી. હાલનાં ખાતાં માટે વાપરો.',
      ml: 'MSSC 31-03-2025 വരെ മാത്രമേ നിക്ഷേപം സ്വീകരിച്ചുള്ളൂ. നിലവിലുള്ള അക്കൗണ്ടുകൾക്ക് മാത്രം ഉപയോഗിക്കുക.',
      or: 'MSSC କେବଳ 31-03-2025 ପର୍ଯ୍ୟନ୍ତ ଜମା ନେଉଥିଲା। ପୁରୁଣା ଖାତା ପାଇଁ ବ୍ୟବହାର କରନ୍ତୁ।',
      pa: 'MSSC ਵਿੱਚ ਜਮ੍ਹਾਂ ਸਿਰਫ਼ 31-03-2025 ਤੱਕ ਲਈ ਗਈ। ਇਸਨੂੰ ਮੌਜੂਦਾ ਖਾਤਿਆਂ ਲਈ ਵਰਤੋ।',
    ),
    Issue.scssAge => _t(
      'SCSS needs age 60+ (55+ for retired civilians, 50+ for retired defence staff).',
      'SCSSಗೆ 60+ ವಯಸ್ಸು ಬೇಕು (ನಿವೃತ್ತ ನಾಗರಿಕ ನೌಕರರಿಗೆ 55+, ರಕ್ಷಣಾ ನಿವೃತ್ತರಿಗೆ 50+).',
      hi: 'SCSS के लिए आयु 60+ चाहिए (सेवानिवृत्त सिविल कर्मचारी 55+, सेवानिवृत्त रक्षा कर्मी 50+)।',
      bn: 'SCSS-এর জন্য বয়স 60+ হতে হবে (অবসরপ্রাপ্ত অসামরিক কর্মীদের 55+, অবসরপ্রাপ্ত প্রতিরক্ষা কর্মীদের 50+)।',
      mr: 'SCSS साठी वय 60+ हवे (निवृत्त नागरी कर्मचाऱ्यांसाठी 55+, निवृत्त संरक्षण कर्मचाऱ्यांसाठी 50+).',
      te: 'SCSS కు వయస్సు 60+ ఉండాలి (రిటైర్డ్ పౌర ఉద్యోగులకు 55+, రిటైర్డ్ రక్షణ సిబ్బందికి 50+).',
      ta: 'SCSS-க்கு வயது 60+ தேவை (ஓய்வுபெற்ற சிவில் ஊழியர்களுக்கு 55+, ஓய்வுபெற்ற பாதுகாப்புப் படையினருக்கு 50+).',
      gu: 'SCSS માટે ઉંમર 60+ જોઈએ (નિવૃત્ત નાગરિક કર્મચારીઓ માટે 55+, નિવૃત્ત સંરક્ષણ કર્મચારીઓ માટે 50+).',
      ml: 'SCSS-ന് പ്രായം 60+ വേണം (വിരമിച്ച സിവിലിയന്മാർക്ക് 55+, വിരമിച്ച പ്രതിരോധ ജീവനക്കാർക്ക് 50+).',
      or: 'SCSS ପାଇଁ ବୟସ 60+ ଦରକାର (ଅବସରପ୍ରାପ୍ତ ନାଗରିକ କର୍ମଚାରୀଙ୍କ ପାଇଁ 55+, ଅବସରପ୍ରାପ୍ତ ପ୍ରତିରକ୍ଷା କର୍ମଚାରୀଙ୍କ ପାଇଁ 50+)।',
      pa: 'SCSS ਲਈ ਉਮਰ 60+ ਚਾਹੀਦੀ ਹੈ (ਸੇਵਾਮੁਕਤ ਸਿਵਲ ਕਰਮਚਾਰੀਆਂ ਲਈ 55+, ਸੇਵਾਮੁਕਤ ਰੱਖਿਆ ਕਰਮਚਾਰੀਆਂ ਲਈ 50+)।',
    ),
    Issue.scssEarlyRetiree => _t(
      'Below 60: only retirees, within 3 months of getting retirement benefits, up to that amount.',
      '60ಕ್ಕಿಂತ ಕಡಿಮೆ: ನಿವೃತ್ತಿ ಸೌಲಭ್ಯ ಪಡೆದ 3 ತಿಂಗಳೊಳಗೆ, ಆ ಮೊತ್ತದವರೆಗೆ ಮಾತ್ರ.',
      hi: '60 से कम: केवल सेवानिवृत्त, सेवानिवृत्ति लाभ मिलने के 3 महीने के भीतर, उसी राशि तक।',
      bn: '60-এর কম: শুধু অবসরপ্রাপ্তরা, অবসরকালীন সুবিধা পাওয়ার 3 মাসের মধ্যে, সেই পরিমাণ পর্যন্ত।',
      mr: '60 पेक्षा कमी: फक्त निवृत्त व्यक्ती, निवृत्ती लाभ मिळाल्यापासून 3 महिन्यांत, त्या रकमेपर्यंत.',
      te: '60 లోపు: రిటైర్ అయినవారు మాత్రమే, రిటైర్మెంట్ ప్రయోజనాలు అందిన 3 నెలల లోపు, ఆ మొత్తం వరకు.',
      ta: '60-க்குக் கீழ்: ஓய்வுபெற்றவர்கள் மட்டும், ஓய்வூதியப் பலன்கள் பெற்ற 3 மாதங்களுக்குள், அந்தத் தொகை வரை.',
      gu: '60 થી ઓછી ઉંમર: ફક્ત નિવૃત્ત, નિવૃત્તિ લાભ મળ્યાના 3 મહિનામાં, એ રકમ સુધી.',
      ml: '60-ൽ താഴെ: വിരമിച്ചവർക്ക് മാത്രം, വിരമിക്കൽ ആനുകൂല്യം ലഭിച്ച് 3 മാസത്തിനകം, ആ തുക വരെ.',
      or: '60 ରୁ କମ: କେବଳ ଅବସରପ୍ରାପ୍ତ, ଅବସର ଲାଭ ପାଇବାର 3 ମାସ ମଧ୍ୟରେ, ସେହି ରାଶି ପର୍ଯ୍ୟନ୍ତ।',
      pa: '60 ਤੋਂ ਘੱਟ: ਸਿਰਫ਼ ਸੇਵਾਮੁਕਤ, ਸੇਵਾਮੁਕਤੀ ਲਾਭ ਮਿਲਣ ਦੇ 3 ਮਹੀਨਿਆਂ ਅੰਦਰ, ਉਸ ਰਕਮ ਤੱਕ।',
    ),
