  String closureRule(ClosureRule r, {int? months, String? rate}) => switch (r) {
    ClosureRule.notYet => _t(
      'Not allowed before $months months.',
      '$months ತಿಂಗಳ ಮೊದಲು ಅನುಮತಿ ಇಲ್ಲ.',
      hi: '$months महीने से पहले अनुमति नहीं।',
      bn: '$months মাসের আগে অনুমতি নেই।',
      mr: '$months महिन्यांपूर्वी परवानगी नाही.',
      te: '$months నెలల ముందు అనుమతి లేదు.',
      ta: '$months மாதங்களுக்கு முன் அனுமதி இல்லை.',
      gu: '$months મહિના પહેલાં મંજૂરી નથી.',
      ml: '$months മാസത്തിന് മുമ്പ് അനുവദനീയമല്ല.',
      or: '$months ମାସ ପୂର୍ବରୁ ଅନୁମତି ନାହିଁ।',
      pa: '$months ਮਹੀਨਿਆਂ ਤੋਂ ਪਹਿਲਾਂ ਮਨਜ਼ੂਰ ਨਹੀਂ।',
    ),
    ClosureRule.notAllowed => _t(
      'Premature closure is allowed only on death of the holder or by court order.',
      'ಖಾತೆದಾರರ ಮರಣ ಅಥವಾ ನ್ಯಾಯಾಲಯದ ಆದೇಶದ ಮೇಲೆ ಮಾತ್ರ ಅವಧಿಪೂರ್ವ ಮುಕ್ತಾಯ.',
      hi: 'समय से पहले बंद करना केवल खाताधारक की मृत्यु या न्यायालय के आदेश पर ही अनुमत है।',
      bn: 'মেয়াদের আগে বন্ধ শুধু অ্যাকাউন্টধারীর মৃত্যু হলে বা আদালতের আদেশে করা যায়।',
      mr: 'मुदतपूर्व बंद फक्त खातेधारकाच्या मृत्यूनंतर किंवा न्यायालयाच्या आदेशाने करता येते.',
      te: 'ఖాతాదారు మరణించినప్పుడు లేదా కోర్టు ఆదేశంతో మాత్రమే ముందస్తు మూసివేతకు అనుమతి ఉంది.',
      ta: 'கணக்குதாரர் இறப்பு அல்லது நீதிமன்ற உத்தரவின் பேரில் மட்டுமே முன்கூட்டியே மூட அனுமதி.',
      gu: 'મુદત પહેલાં બંધ ફક્ત ખાતેદારના મૃત્યુ પર અથવા કોર્ટના આદેશથી જ થઈ શકે.',
      ml: 'ഉടമയുടെ മരണത്തിലോ കോടതി ഉത്തരവിലോ മാത്രമേ കാലാവധിക്ക് മുമ്പ് അവസാനിപ്പിക്കാനാകൂ.',
      or: 'ଅକାଳ ବନ୍ଦ କେବଳ ଖାତାଧାରୀଙ୍କ ମୃତ୍ୟୁ କିମ୍ବା କୋର୍ଟ ଆଦେଶରେ ଅନୁମତି।',
      pa: 'ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਬੰਦ ਕਰਨਾ ਸਿਰਫ਼ ਖਾਤਾਧਾਰਕ ਦੀ ਮੌਤ ਜਾਂ ਅਦਾਲਤੀ ਹੁਕਮ ’ਤੇ ਮਨਜ਼ੂਰ ਹੈ।',
    ),
    ClosureRule.useWithdrawal => _t(
      'Use the withdrawal rules below.',
      'ಕೆಳಗಿನ ಹಿಂಪಡೆಯುವ ನಿಯಮಗಳನ್ನು ನೋಡಿ.',
      hi: 'नीचे दिए गए निकासी नियमों का उपयोग करें।',
      bn: 'নিচের টাকা তোলার নিয়ম দেখুন।',
      mr: 'खालील पैसे काढण्याचे नियम वापरा.',
      te: 'క్రింది ఉపసంహరణ నియమాలను ఉపయోగించండి.',
      ta: 'கீழே உள்ள பணம் எடுக்கும் விதிகளைப் பயன்படுத்தவும்.',
      gu: 'નીચેના ઉપાડના નિયમો વાપરો.',
      ml: 'താഴെയുള്ള പിൻവലിക്കൽ നിയമങ്ങൾ നോക്കുക.',
