      hi: '1–3 वर्ष: जमा का 2% काटा जाएगा; 3 वर्ष के बाद: 1%।',
      bn: '1–3 বছর: জমার 2% কাটা হয়; 3 বছরের পরে: 1%।',
      mr: '1–3 वर्षे: ठेवीच्या 2% कपात; 3 वर्षांनंतर: 1%.',
      te: '1–3 సంవత్సరాలు: డిపాజిట్‌లో 2% తగ్గింపు; 3 సంవత్సరాల తర్వాత: 1%.',
      ta: '1–3 ஆண்டுகள்: வைப்பில் 2% கழிக்கப்படும்; 3 ஆண்டுகளுக்குப் பின்: 1%.',
      gu: '1–3 વર્ષ: જમાના 2% કપાશે; 3 વર્ષ પછી: 1%.',
      ml: '1–3 വർഷം: നിക്ഷേപത്തിന്റെ 2% കിഴിക്കും; 3 വർഷത്തിന് ശേഷം: 1%.',
      or: '1–3 ବର୍ଷ: ଜମାର 2% କଟାଯାଏ; 3 ବର୍ଷ ପରେ: 1%।',
      pa: '1–3 ਸਾਲ: ਜਮ੍ਹਾਂ ਦਾ 2% ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ; 3 ਸਾਲ ਬਾਅਦ: 1%।',
    ),
    ClosureRule.scssRecover => _t(
      'Before 1 year: interest paid is recovered from the deposit.',
      '1 ವರ್ಷದ ಮೊದಲು: ಪಾವತಿಸಿದ ಬಡ್ಡಿಯನ್ನು ಠೇವಣಿಯಿಂದ ವಸೂಲಿ.',
      hi: '1 वर्ष से पहले: भुगतान किया गया ब्याज जमा से वसूला जाएगा।',
      bn: '1 বছরের আগে: দেওয়া সুদ জমা থেকে কেটে নেওয়া হয়।',
      mr: '1 वर्षापूर्वी: दिलेले व्याज ठेवीतून वसूल केले जाते.',
      te: '1 సంవత్సరం లోపు: చెల్లించిన వడ్డీని డిపాజిట్ నుండి తిరిగి వసూలు చేస్తారు.',
      ta: '1 ஆண்டுக்கு முன்: செலுத்திய வட்டி வைப்பிலிருந்து திரும்பப் பெறப்படும்.',
      gu: '1 વર્ષ પહેલાં: ચૂકવેલ વ્યાજ જમામાંથી વસૂલાશે.',
      ml: '1 വർഷത്തിന് മുമ്പ്: നൽകിയ പലിശ നിക്ഷേപത്തിൽ നിന്ന് തിരിച്ചുപിടിക്കും.',
      or: '1 ବର୍ଷ ପୂର୍ବରୁ: ଦିଆଯାଇଥିବା ସୁଧ ଜମାରୁ କଟାଯାଏ।',
      pa: '1 ਸਾਲ ਤੋਂ ਪਹਿਲਾਂ: ਦਿੱਤਾ ਵਿਆਜ ਜਮ੍ਹਾਂ ਵਿੱਚੋਂ ਵਾਪਸ ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ।',
    ),
    ClosureRule.scssDeduct => _t(
      '1–2 years: 1.5% deducted; after 2 years: 1%. Extended accounts: no deduction after 1 year.',
      '1–2 ವರ್ಷ: 1.5% ಕಡಿತ; 2 ವರ್ಷದ ನಂತರ: 1%. ವಿಸ್ತರಿಸಿದ ಖಾತೆ: 1 ವರ್ಷದ ನಂತರ ಕಡಿತ ಇಲ್ಲ.',
      hi: '1–2 वर्ष: 1.5% कटौती; 2 वर्ष के बाद: 1%। बढ़ाए गए खाते: 1 वर्ष के बाद कोई कटौती नहीं।',
      bn: '1–2 বছর: 1.5% কাটা হয়; 2 বছরের পরে: 1%। মেয়াদ বাড়ানো অ্যাকাউন্টে 1 বছর পরে কিছু কাটা হয় না।',
      mr: '1–2 वर्षे: 1.5% कपात; 2 वर्षांनंतर: 1%. मुदतवाढ दिलेली खाती: 1 वर्षानंतर कपात नाही.',
      te: '1–2 సంవత్సరాలు: 1.5% తగ్గింపు; 2 సంవత్సరాల తర్వాత: 1%. పొడిగించిన ఖాతాలు: 1 సంవత్సరం తర్వాత తగ్గింపు లేదు.',
      ta: '1–2 ஆண்டுகள்: 1.5% கழிக்கப்படும்; 2 ஆண்டுகளுக்குப் பின்: 1%. நீட்டித்த கணக்குகள்: 1 ஆண்டுக்குப் பின் கழிவு இல்லை.',
      gu: '1–2 વર્ષ: 1.5% કપાશે; 2 વર્ષ પછી: 1%. લંબાવેલાં ખાતાં: 1 વર્ષ પછી કોઈ કપાત નહીં.',
      ml: '1–2 വർഷം: 1.5% കിഴിക്കും; 2 വർഷത്തിന് ശേഷം: 1%. നീട്ടിയ അക്കൗണ്ടുകൾ: 1 വർഷത്തിന് ശേഷം കിഴിവില്ല.',
      or: '1–2 ବର୍ଷ: 1.5% କଟାଯାଏ; 2 ବର୍ଷ ପରେ: 1%। ବୃଦ୍ଧି କରାଯାଇଥିବା ଖାତା: 1 ବର୍ଷ ପରେ କଟତି ନାହିଁ।',
      pa: '1–2 ਸਾਲ: 1.5% ਕਟੌਤੀ; 2 ਸਾਲ ਬਾਅਦ: 1%। ਵਧਾਏ ਖਾਤੇ: 1 ਸਾਲ ਬਾਅਦ ਕੋਈ ਕਟੌਤੀ ਨਹੀਂ।',
    ),
    ClosureRule.kvpTable => _t(
      'After 2½ years, as per the official table (estimated here).',
      '2½ ವರ್ಷದ ನಂತರ, ಅಧಿಕೃತ ಪಟ್ಟಿಯಂತೆ (ಇಲ್ಲಿ ಅಂದಾಜು).',
      hi: '2½ वर्ष के बाद, आधिकारिक तालिका के अनुसार (यहाँ अनुमानित)।',
      bn: '2½ বছর পরে, সরকারি তালিকা অনুযায়ী (এখানে আনুমানিক)।',
      mr: '2½ वर्षांनंतर, अधिकृत तक्त्यानुसार (येथे अंदाजे).',
      te: '2½ సంవత్సరాల తర్వాత, అధికారిక పట్టిక ప్రకారం (ఇక్కడ అంచనా).',
      ta: '2½ ஆண்டுகளுக்குப் பின், அதிகாரப்பூர்வ அட்டவணைப்படி (இங்கே மதிப்பீடு).',
      gu: '2½ વર્ષ પછી, સત્તાવાર કોષ્ટક મુજબ (અહીં અંદાજિત).',
