  String get ppfWithdrawalNote => _t(
    'Once a year from year 7: up to 50% of the lower of the balance 4 years earlier or last year.',
    '7ನೇ ವರ್ಷದಿಂದ ವರ್ಷಕ್ಕೊಮ್ಮೆ: 4 ವರ್ಷ ಹಿಂದಿನ ಅಥವಾ ಕಳೆದ ವರ್ಷದ ಶಿಲ್ಕಿನಲ್ಲಿ ಕಡಿಮೆಯದರ 50%ವರೆಗೆ.',
    hi: 'वर्ष 7 से वर्ष में एक बार: 4 वर्ष पहले या पिछले वर्ष की शेष राशि में से जो कम हो, उसका 50% तक।',
    bn: '7ম বছর থেকে বছরে একবার: 4 বছর আগের বা গত বছরের ব্যালান্সের মধ্যে যেটি কম, তার 50% পর্যন্ত।',
    mr: '7 व्या वर्षापासून वर्षातून एकदा: 4 वर्षांपूर्वीची किंवा मागील वर्षाची, यापैकी कमी शिल्लकेच्या 50% पर्यंत.',
    te: '7వ సంవత్సరం నుండి సంవత్సరానికి ఒకసారి: 4 సంవత్సరాల క్రితం లేదా గత సంవత్సరం నిల్వలో ఏది తక్కువో దానిలో 50% వరకు.',
    ta: '7-ஆம் ஆண்டு முதல் ஆண்டுக்கு ஒருமுறை: 4 ஆண்டுகளுக்கு முந்தைய அல்லது கடந்த ஆண்டு இருப்பில் குறைவானதில் 50% வரை.',
    gu: '7મા વર્ષથી વર્ષમાં એક વાર: 4 વર્ષ પહેલાંના કે ગયા વર્ષના બેલેન્સમાંથી ઓછા હોય તેના 50% સુધી.',
    ml: '7-ാം വർഷം മുതൽ വർഷത്തിൽ ഒരിക്കൽ: 4 വർഷം മുമ്പത്തെയോ കഴിഞ്ഞ വർഷത്തെയോ ബാലൻസിൽ കുറഞ്ഞതിന്റെ 50% വരെ.',
    or: '7ମ ବର୍ଷରୁ ବର୍ଷକୁ ଥରେ: 4 ବର୍ଷ ପୂର୍ବର କିମ୍ବା ଗତ ବର୍ଷର ବାଲାନ୍ସ ମଧ୍ୟରୁ କମ ଟିର 50% ପର୍ଯ୍ୟନ୍ତ।',
    pa: 'ਸਾਲ 7 ਤੋਂ ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ: 4 ਸਾਲ ਪਹਿਲਾਂ ਜਾਂ ਪਿਛਲੇ ਸਾਲ ਦੇ ਬਕਾਏ ਵਿੱਚੋਂ ਘੱਟ ਦਾ 50% ਤੱਕ।',
  );
  String get ssyWithdrawalNote => _t(
    'After the girl turns 18 (or passes 10th): up to 50% of last year\'s balance.',
    'ಮಗುವಿಗೆ 18 ತುಂಬಿದ ನಂತರ (ಅಥವಾ 10ನೇ ತರಗತಿ ಪಾಸಾದ ನಂತರ): ಕಳೆದ ವರ್ಷದ ಶಿಲ್ಕಿನ 50%ವರೆಗೆ.',
