  String get compareNote => _t(
    'RD: the amount is split into 60 monthly instalments. MIS and TD pay interest out; the total includes it.',
    'RD: ಮೊತ್ತವನ್ನು 60 ಮಾಸಿಕ ಕಂತುಗಳಾಗಿ ಹಂಚಲಾಗಿದೆ. MIS ಮತ್ತು TD ಬಡ್ಡಿ ಪಾವತಿಸುತ್ತವೆ; ಒಟ್ಟಿನಲ್ಲಿ ಸೇರಿದೆ.',
    hi: 'RD: राशि को 60 मासिक किस्तों में बाँटा जाता है। MIS और TD ब्याज का भुगतान करते हैं; कुल में वह शामिल है।',
    bn: 'RD: পরিমাণটি 60টি মাসিক কিস্তিতে ভাগ করা হয়। MIS ও TD সুদ দিয়ে দেয়; মোট হিসাবে তা ধরা আছে।',
    mr: 'RD: रक्कम 60 मासिक हप्त्यांमध्ये विभागली जाते. MIS आणि TD व्याज बाहेर देतात; एकूण रकमेत ते समाविष्ट आहे.',
    te: 'RD: మొత్తాన్ని 60 నెలవారీ వాయిదాలుగా విభజించారు. MIS మరియు TD వడ్డీని చెల్లిస్తాయి; మొత్తంలో అది కలిసి ఉంది.',
    ta: 'RD: தொகை 60 மாதத் தவணைகளாகப் பிரிக்கப்படுகிறது. MIS மற்றும் TD வட்டியை வெளியே செலுத்தும்; மொத்தத்தில் அது சேர்க்கப்பட்டுள்ளது.',
    gu: 'RD: રકમ 60 માસિક હપ્તામાં વહેંચાય છે. MIS અને TD વ્યાજ ચૂકવી દે છે; કુલમાં તે સામેલ છે.',
    ml: 'RD: തുക 60 പ്രതിമാസ തവണകളായി വിഭജിക്കുന്നു. MIS, TD എന്നിവ പലിശ പുറത്തേക്ക് നൽകുന്നു; ആകെ തുകയിൽ അത് ഉൾപ്പെടുന്നു.',
    or: 'RD: ରାଶିକୁ 60 ମାସିକ କିସ୍ତିରେ ଭାଗ କରାଯାଏ। MIS ଓ TD ସୁଧ ଦେଇଦିଅନ୍ତି; ମୋଟରେ ଏହା ସାମିଲ।',
