  /// Counter steps to open [s] for a [h] holder, in order.
  List<String> openingSteps(Scheme s, Holding h) {
    if (s == Scheme.mssc) {
      return [
        _t(
          'Closed for new accounts since 1 April 2025. Use this app only for existing accounts.',
          '1 ಏಪ್ರಿಲ್ 2025ರಿಂದ ಹೊಸ ಖಾತೆಗಳಿಗೆ ಮುಚ್ಚಲಾಗಿದೆ. ಈಗಿನ ಖಾತೆಗಳಿಗೆ ಮಾತ್ರ ಈ ಆ್ಯಪ್ ಬಳಸಿ.',
          hi: '1 अप्रैल 2025 से नए खातों के लिए बंद। यह ऐप केवल मौजूदा खातों के लिए उपयोग करें।',
          bn: '1 এপ্রিল 2025 থেকে নতুন অ্যাকাউন্ট খোলা বন্ধ। এই অ্যাপ শুধু পুরোনো অ্যাকাউন্টের জন্য ব্যবহার করুন।',
          mr: '1 एप्रिल 2025 पासून नवीन खात्यांसाठी बंद. हे ॲप फक्त सध्याच्या खात्यांसाठी वापरा.',
          te: '1 ఏప్రిల్ 2025 నుండి కొత్త ఖాతాలకు మూసివేయబడింది. ఉన్న ఖాతాలకు మాత్రమే ఈ యాప్ ఉపయోగించండి.',
          ta: '1 ஏப்ரல் 2025 முதல் புதிய கணக்குகளுக்கு மூடப்பட்டது. ஏற்கனவே உள்ள கணக்குகளுக்கு மட்டும் இந்தச் செயலியைப் பயன்படுத்தவும்.',
          gu: '1 એપ્રિલ 2025 થી નવાં ખાતાં માટે બંધ. આ એપ ફક્ત હાલનાં ખાતાં માટે વાપરો.',
          ml: '2025 ഏപ്രിൽ 1 മുതൽ പുതിയ അക്കൗണ്ടുകൾ തുറക്കുന്നില്ല. നിലവിലുള്ള അക്കൗണ്ടുകൾക്ക് മാത്രം ഈ ആപ്പ് ഉപയോഗിക്കുക.',
          or: '1 ଏପ୍ରିଲ 2025 ଠାରୁ ନୂଆ ଖାତା ପାଇଁ ବନ୍ଦ। ଏହି ଆପ କେବଳ ପୁରୁଣା ଖାତା ପାଇଁ ବ୍ୟବହାର କରନ୍ତୁ।',
          pa: '1 ਅਪ੍ਰੈਲ 2025 ਤੋਂ ਨਵੇਂ ਖਾਤਿਆਂ ਲਈ ਬੰਦ। ਇਹ ਐਪ ਸਿਰਫ਼ ਮੌਜੂਦਾ ਖਾਤਿਆਂ ਲਈ ਵਰਤੋ।',
        ),
