        bn: 'অ্যাকাউন্ট খোলার ফর্ম (সব প্রকল্পের জন্য একটিই ফর্ম) পূরণ করে ${s.code}-এ টিক দিন।',
        mr: 'खाते उघडण्याचा फॉर्म (सर्व योजनांसाठी एकच फॉर्म) भरा आणि ${s.code} वर खूण करा.',
