        pa: 'ਖਾਤਾ ਖੋਲ੍ਹਣ ਦਾ ਫ਼ਾਰਮ ਭਰੋ (ਸਾਰੀਆਂ ਯੋਜਨਾਵਾਂ ਲਈ ਇੱਕੋ ਫ਼ਾਰਮ) ਅਤੇ ${s.code} ’ਤੇ ਨਿਸ਼ਾਨ ਲਾਓ।',
