        ta: 'புதிய வாடிக்கையாளர்: KYC படிவத்தை நிரப்பவும். ஆதார், PAN (அல்லது Form 60) மற்றும் புகைப்படத்தைப் பெறவும்.',
        gu: 'નવા ગ્રાહક: KYC ફોર્મ ભરો. આધાર, PAN (અથવા Form 60) અને ફોટો લો.',
        ml: 'പുതിയ ഉപഭോക്താവ്: KYC ഫോം പൂരിപ്പിക്കുക. ആധാർ, PAN (അല്ലെങ്കിൽ Form 60), ഫോട്ടോ എന്നിവ വാങ്ങുക.',
