        pa: 'ਨਵਾਂ ਗਾਹਕ: KYC ਫ਼ਾਰਮ ਭਰੋ। ਆਧਾਰ, PAN (ਜਾਂ Form 60) ਅਤੇ ਫ਼ੋਟੋ ਲਓ।',
