      if (h == Holding.joint)
        _t(
          'Joint: up to 3 adults; each one gives KYC and signs. For SCSS the joint holder can only be the spouse.',
          'ಜಂಟಿ: 3 ವಯಸ್ಕರವರೆಗೆ; ಪ್ರತಿಯೊಬ್ಬರೂ KYC ನೀಡಿ ಸಹಿ ಮಾಡಬೇಕು. SCSSನಲ್ಲಿ ಜಂಟಿ ಖಾತೆದಾರರು ಪತಿ/ಪತ್ನಿ ಮಾತ್ರ.',
          hi: 'संयुक्त: अधिकतम 3 वयस्क; हर एक KYC दे और हस्ताक्षर करे। SCSS में संयुक्त धारक केवल पति/पत्नी हो सकते हैं।',
          bn: 'যৌথ: 3 জন প্রাপ্তবয়স্ক পর্যন্ত; প্রত্যেকে KYC দেবেন ও সই করবেন। SCSS-এ যৌথ অ্যাকাউন্টধারী শুধু স্বামী/স্ত্রী হতে পারেন।',
          mr: 'संयुक्त: 3 प्रौढांपर्यंत; प्रत्येकाने KYC द्यावे आणि सही करावी. SCSS साठी संयुक्त खातेधारक फक्त जोडीदार असू शकतो.',
          te: 'జాయింట్: గరిష్ఠంగా 3 పెద్దలు; ప్రతి ఒక్కరూ KYC ఇచ్చి సంతకం చేయాలి. SCSS లో జాయింట్ ఖాతాదారు జీవిత భాగస్వామి మాత్రమే కావచ్చు.',
          ta: 'கூட்டு: 3 பெரியவர்கள் வரை; ஒவ்வொருவரும் KYC வழங்கி கையொப்பமிட வேண்டும். SCSS-இல் கூட்டுக் கணக்குதாரர் வாழ்க்கைத் துணை மட்டுமே.',
