          ml: 'ജോയിന്റ്: 3 മുതിർന്നവർ വരെ; ഓരോരുത്തരും KYC നൽകി ഒപ്പിടണം. SCSS-ൽ ജോയിന്റ് ഉടമ ജീവിതപങ്കാളി മാത്രമാകാം.',
          or: 'ଯୁଗ୍ମ: 3 ଜଣ ବୟସ୍କ ପର୍ଯ୍ୟନ୍ତ; ପ୍ରତ୍ୟେକ KYC ଦେଇ ଦସ୍ତଖତ କରନ୍ତି। SCSS ପାଇଁ ଯୁଗ୍ମ ଖାତାଧାରୀ କେବଳ ପତି/ପତ୍ନୀ ହୋଇପାରିବେ।',
