          bn: 'নাবালক: অভিভাবক ফর্মে সই করবেন ও নিজের KYC দেবেন, সঙ্গে শিশুর জন্ম সনদ।',
          mr: 'अल्पवयीन: पालक फॉर्मवर सही करतात आणि स्वतःचे KYC देतात, सोबत मुलाचा/मुलीचा जन्म दाखला.',
          te: 'మైనర్: సంరక్షకుడు ఫారంపై సంతకం చేసి తన సొంత KYC తో పాటు పిల్లల జనన ధృవీకరణ పత్రం ఇవ్వాలి.',
          ta: 'மைனர்: பாதுகாவலர் படிவத்தில் கையொப்பமிட்டு, தமது KYC-யையும் குழந்தையின் பிறப்புச் சான்றிதழையும் வழங்க வேண்டும்.',
          gu: 'સગીર: વાલી ફોર્મ પર સહી કરે અને પોતાનું KYC આપે, સાથે બાળકનું જન્મ પ્રમાણપત્ર.',
