            bn: 'এখনই প্রথম কিস্তি নিন। 1–15 তারিখে খোলা হলে: প্রতি মাসে 15 তারিখের মধ্যে জমা; 16 তারিখ বা পরে খোলা হলে: মাসের শেষের মধ্যে।',
            mr: 'पहिला हप्ता आताच घ्या. 1–15 तारखेला उघडल्यास: दरमहा 15 तारखेपर्यंत भरा; 16 तारखेला किंवा नंतर उघडल्यास: महिनाअखेरपर्यंत.',
            te: 'మొదటి వాయిదా ఇప్పుడే తీసుకోండి. 1–15 తేదీల్లో తెరిస్తే: ప్రతి నెలా 15వ తేదీ లోపు చెల్లించాలి; 16వ తేదీ లేదా తర్వాత తెరిస్తే: నెలాఖరు లోపు.',
            ta: 'முதல் தவணையை இப்போதே பெறவும். 1–15 தேதிகளில் தொடங்கினால்: ஒவ்வொரு மாதமும் 15-ஆம் தேதிக்குள் செலுத்த வேண்டும்; 16-ஆம் தேதி அல்லது பின் தொடங்கினால்: மாத இறுதிக்குள்.',
            gu: 'પહેલો હપ્તો હમણાં લો. 1–15 તારીખે ખોલ્યું હોય: દર મહિને 15 તારીખ સુધી ભરો; 16 કે પછી ખોલ્યું હોય: મહિનાના અંત સુધી.',
            ml: 'ആദ്യ തവണ ഇപ്പോൾ വാങ്ങുക. 1–15 തീയതികളിൽ തുറന്നാൽ: എല്ലാ മാസവും 15-നകം അടയ്ക്കണം; 16-നോ ശേഷമോ തുറന്നാൽ: മാസാവസാനത്തിനകം.',
            or: 'ପ୍ରଥମ କିସ୍ତି ଏବେ ନିଅନ୍ତୁ। 1–15 ତାରିଖରେ ଖୋଲିଲେ: ପ୍ରତି ମାସ 15 ତାରିଖ ସୁଦ୍ଧା ଦିଅନ୍ତୁ; 16 ତାରିଖ କିମ୍ବା ପରେ ଖୋଲିଲେ: ମାସ ଶେଷ ସୁଦ୍ଧା।',
            pa: 'ਪਹਿਲੀ ਕਿਸ਼ਤ ਹੁਣੇ ਲਓ। 1–15 ਤਰੀਕ ਨੂੰ ਖੁੱਲ੍ਹਿਆ: ਹਰ ਮਹੀਨੇ 15 ਤਰੀਕ ਤੱਕ ਭਰੋ; 16 ਤਰੀਕ ਜਾਂ ਬਾਅਦ ਖੁੱਲ੍ਹਿਆ: ਮਹੀਨੇ ਦੇ ਅੰਤ ਤੱਕ।',
          ),
          _t(
            'A missed month costs a default fee of ₹1 for every ₹100.',
            'ತಪ್ಪಿದ ತಿಂಗಳಿಗೆ ಪ್ರತಿ ₹100ಕ್ಕೆ ₹1 ದಂಡ.',
            hi: 'किसी महीने की किस्त छूटने पर हर ₹100 पर ₹1 डिफ़ॉल्ट शुल्क लगता है।',
            bn: 'কোনো মাসে জমা বাদ গেলে প্রতি ₹100-এ ₹1 ডিফল্ট ফি লাগে।',
            mr: 'हप्ता चुकल्यास प्रत्येक ₹100 मागे ₹1 विलंब शुल्क लागते.',
            te: 'ఒక నెల కట్టకపోతే ప్రతి ₹100 కి ₹1 డిఫాల్ట్ రుసుము పడుతుంది.',
            ta: 'தவறிய மாதத்துக்கு ஒவ்வொரு ₹100-க்கும் ₹1 தாமதக் கட்டணம்.',
            gu: 'ચૂકેલા મહિના માટે દર ₹100 પર ₹1 ડિફોલ્ટ ફી લાગે છે.',
            ml: 'മുടങ്ങിയ ഓരോ മാസത്തിനും ഓരോ ₹100-നും ₹1 പിഴ.',
            or: 'ଗୋଟିଏ ମାସ ଛାଡ଼ିଲେ ପ୍ରତି ₹100 ପାଇଁ ₹1 ଡିଫଲ୍ଟ ଫି ଲାଗେ।',
            pa: 'ਖੁੰਝੇ ਮਹੀਨੇ ਲਈ ਹਰ ₹100 ’ਤੇ ₹1 ਡਿਫਾਲਟ ਫੀਸ ਲੱਗਦੀ ਹੈ।',
          ),
