        Scheme.td1 || Scheme.td2 || Scheme.td3 || Scheme.td5 => [
          _t(
            'Choose the term: 1, 2, 3 or 5 years. Only the 5-year TD counts for section 80C.',
            'ಅವಧಿ ಆಯ್ಕೆ ಮಾಡಿ: 1, 2, 3 ಅಥವಾ 5 ವರ್ಷ. 5 ವರ್ಷದ TD ಮಾತ್ರ 80C ಸೆಕ್ಷನ್‌ಗೆ ಅರ್ಹ.',
            hi: 'अवधि चुनें: 1, 2, 3 या 5 वर्ष। केवल 5 वर्षीय TD धारा 80C में गिनी जाती है।',
            bn: 'মেয়াদ বেছে নিন: 1, 2, 3 বা 5 বছর। শুধু 5 বছরের TD ধারা 80C-তে গণ্য হয়।',
            mr: 'मुदत निवडा: 1, 2, 3 किंवा 5 वर्षे. फक्त 5 वर्षांची TD कलम 80C साठी पात्र आहे.',
            te: 'వ్యవధి ఎంచుకోండి: 1, 2, 3 లేదా 5 సంవత్సరాలు. 5 సంవత్సరాల TD మాత్రమే సెక్షన్ 80C కి వర్తిస్తుంది.',
            ta: 'காலத்தைத் தேர்வுசெய்யவும்: 1, 2, 3 அல்லது 5 ஆண்டுகள். 5 ஆண்டு TD மட்டுமே பிரிவு 80C-க்குக் கணக்கிடப்படும்.',
            gu: 'મુદત પસંદ કરો: 1, 2, 3 કે 5 વર્ષ. ફક્ત 5 વર્ષની TD જ કલમ 80C માં ગણાય છે.',
            ml: 'കാലാവധി തിരഞ്ഞെടുക്കുക: 1, 2, 3 അല്ലെങ്കിൽ 5 വർഷം. 5 വർഷ TD മാത്രമേ സെക്ഷൻ 80C-ന് പരിഗണിക്കൂ.',
            or: 'ଅବଧି ବାଛନ୍ତୁ: 1, 2, 3 କିମ୍ବା 5 ବର୍ଷ। କେବଳ 5 ବର୍ଷ TD ଧାରା 80C ପାଇଁ ଗଣାଯାଏ।',
            pa: 'ਮਿਆਦ ਚੁਣੋ: 1, 2, 3 ਜਾਂ 5 ਸਾਲ। ਸਿਰਫ਼ 5 ਸਾਲਾ TD ਧਾਰਾ 80C ਲਈ ਗਿਣੀ ਜਾਂਦੀ ਹੈ।',
          ),
        ],
        Scheme.mis => [
          _t(
            'Link a Post Office savings account; monthly interest is credited there.',
            'ಅಂಚೆ ಉಳಿತಾಯ ಖಾತೆ ಜೋಡಿಸಿ; ಮಾಸಿಕ ಬಡ್ಡಿ ಅದಕ್ಕೆ ಜಮೆಯಾಗುತ್ತದೆ.',
            hi: 'डाकघर बचत खाता लिंक करें; मासिक ब्याज उसी में जमा होगा।',
            bn: 'একটি ডাকঘর সঞ্চয় অ্যাকাউন্ট লিঙ্ক করুন; মাসিক সুদ সেখানে জমা হবে।',
            mr: 'टपाल कार्यालय बचत खाते जोडा; मासिक व्याज त्यात जमा होते.',
            te: 'తపాలా కార్యాలయ పొదుపు ఖాతాను లింక్ చేయండి; నెలవారీ వడ్డీ అందులో జమ అవుతుంది.',
            ta: 'அஞ்சலக சேமிப்புக் கணக்கை இணைக்கவும்; மாத வட்டி அதில் வரவு வைக்கப்படும்.',
            gu: 'પોસ્ટ ઓફિસ બચત ખાતું લિંક કરો; માસિક વ્યાજ તેમાં જમા થાય છે.',
            ml: 'പോസ്റ്റ് ഓഫീസ് സേവിംഗ്സ് അക്കൗണ്ട് ബന്ധിപ്പിക്കുക; പ്രതിമാസ പലിശ അതിലേക്ക് വരവ് വെക്കും.',
            or: 'ଡାକଘର ସଞ୍ଚୟ ଖାତା ଲିଙ୍କ କରନ୍ତୁ; ମାସିକ ସୁଧ ସେଥିରେ ଜମା ହୁଏ।',
            pa: 'ਡਾਕਘਰ ਬਚਤ ਖਾਤਾ ਜੋੜੋ; ਮਾਸਿਕ ਵਿਆਜ ਉਸ ਵਿੱਚ ਜਮ੍ਹਾਂ ਹੁੰਦਾ ਹੈ।',
          ),
        ],
        Scheme.scss => [
          _t(
            'Link a Post Office savings account for the quarterly interest.',
            'ತ್ರೈಮಾಸಿಕ ಬಡ್ಡಿಗಾಗಿ ಅಂಚೆ ಉಳಿತಾಯ ಖಾತೆ ಜೋಡಿಸಿ.',
            hi: 'तिमाही ब्याज के लिए डाकघर बचत खाता लिंक करें।',
            bn: 'ত্রৈমাসিক সুদের জন্য একটি ডাকঘর সঞ্চয় অ্যাকাউন্ট লিঙ্ক করুন।',
