            ml: 'ത്രൈമാസ പലിശയ്ക്കായി പോസ്റ്റ് ഓഫീസ് സേവിംഗ്സ് അക്കൗണ്ട് ബന്ധിപ്പിക്കുക.',
            or: 'ତ୍ରୈମାସିକ ସୁଧ ପାଇଁ ଡାକଘର ସଞ୍ଚୟ ଖାତା ଲିଙ୍କ କରନ୍ତୁ।',
            pa: 'ਤਿਮਾਹੀ ਵਿਆਜ ਲਈ ਡਾਕਘਰ ਬਚਤ ਖਾਤਾ ਜੋੜੋ।',
          ),
          _t(
            'Below 60: take the retirement benefit papers; open within 3 months of getting the benefits.',
            '60ಕ್ಕಿಂತ ಕಡಿಮೆ: ನಿವೃತ್ತಿ ಸೌಲಭ್ಯದ ದಾಖಲೆ ಪಡೆಯಿರಿ; ಸೌಲಭ್ಯ ಪಡೆದ 3 ತಿಂಗಳೊಳಗೆ ತೆರೆಯಬೇಕು.',
            hi: '60 से कम: सेवानिवृत्ति लाभ के कागज़ात लें; लाभ मिलने के 3 महीने के भीतर खाता खोलें।',
            bn: '60-এর কম: অবসরকালীন সুবিধার কাগজপত্র নিন; সুবিধা পাওয়ার 3 মাসের মধ্যে খুলুন।',
            mr: '60 पेक्षा कमी: निवृत्ती लाभाची कागदपत्रे आणा; लाभ मिळाल्यापासून 3 महिन्यांत खाते उघडा.',
            te: '60 లోపు: రిటైర్మెంట్ ప్రయోజనాల పత్రాలు తీసుకోండి; ప్రయోజనాలు అందిన 3 నెలల లోపు తెరవాలి.',
            ta: '60-க்குக் கீழ்: ஓய்வூதியப் பலன் ஆவணங்களைப் பெறவும்; பலன்கள் பெற்ற 3 மாதங்களுக்குள் தொடங்கவும்.',
            gu: '60 થી ઓછી ઉંમર: નિવૃત્તિ લાભના કાગળો લો; લાભ મળ્યાના 3 મહિનામાં ખોલો.',
            ml: '60-ൽ താഴെ: വിരമിക്കൽ ആനുകൂല്യ രേഖകൾ വാങ്ങുക; ആനുകൂല്യം ലഭിച്ച് 3 മാസത്തിനകം തുറക്കണം.',
            or: '60 ରୁ କମ: ଅବସର ଲାଭ କାଗଜପତ୍ର ନିଅନ୍ତୁ; ଲାଭ ପାଇବାର 3 ମାସ ମଧ୍ୟରେ ଖୋଲନ୍ତୁ।',
            pa: '60 ਤੋਂ ਘੱਟ: ਸੇਵਾਮੁਕਤੀ ਲਾਭ ਦੇ ਕਾਗਜ਼ ਲਓ; ਲਾਭ ਮਿਲਣ ਦੇ 3 ਮਹੀਨਿਆਂ ਅੰਦਰ ਖੋਲ੍ਹੋ।',
          ),
        ],
        Scheme.ppf => [
          _t(
            'Only one PPF account per person. Deposit ₹500 to ₹1.5 lakh in each financial year.',
            'ಒಬ್ಬರಿಗೆ ಒಂದೇ PPF ಖಾತೆ. ಪ್ರತಿ ಹಣಕಾಸು ವರ್ಷ ₹500ರಿಂದ ₹1.5 ಲಕ್ಷ ಠೇವಣಿ.',
            hi: 'प्रति व्यक्ति केवल एक PPF खाता। हर वित्त वर्ष में ₹500 से ₹1.5 लाख जमा करें।',
            bn: 'প্রতি ব্যক্তির শুধু একটি PPF অ্যাকাউন্ট। প্রতি আর্থিক বছরে ₹500 থেকে ₹1.5 লাখ জমা।',
