            te: 'ఒక్కో వ్యక్తికి ఒకే PPF ఖాతా. ప్రతి ఆర్థిక సంవత్సరంలో ₹500 నుండి ₹1.5 లక్షల వరకు జమ చేయండి.',
            ta: 'ஒருவருக்கு ஒரு PPF கணக்கு மட்டுமே. ஒவ்வொரு நிதியாண்டிலும் ₹500 முதல் ₹1.5 லட்சம் வரை வைப்பு செய்யலாம்.',
            gu: 'વ્યક્તિ દીઠ ફક્ત એક PPF ખાતું. દરેક નાણાકીય વર્ષમાં ₹500 થી ₹1.5 લાખ જમા કરો.',
