            pa: 'ਹਰ ਵਿਅਕਤੀ ਦਾ ਸਿਰਫ਼ ਇੱਕ PPF ਖਾਤਾ। ਹਰ ਵਿੱਤੀ ਸਾਲ ਵਿੱਚ ₹500 ਤੋਂ ₹1.5 ਲੱਖ ਜਮ੍ਹਾਂ ਕਰੋ।',
          ),
