        Scheme.ssy => [
          _t(
            'Opened by the parent or guardian for a girl below 10, with her birth certificate. At most two girls per family (more only for twins or triplets).',
            'ಪೋಷಕರು 10 ವರ್ಷದೊಳಗಿನ ಹೆಣ್ಣು ಮಗುವಿಗೆ ಜನನ ಪ್ರಮಾಣಪತ್ರದೊಂದಿಗೆ ತೆರೆಯುತ್ತಾರೆ. ಕುಟುಂಬಕ್ಕೆ ಗರಿಷ್ಠ ಇಬ್ಬರು ಹೆಣ್ಣು ಮಕ್ಕಳು (ಅವಳಿ/ತ್ರಿವಳಿಗೆ ಮಾತ್ರ ಹೆಚ್ಚು).',
            hi: '10 वर्ष से कम आयु की बालिका के लिए माता-पिता या अभिभावक द्वारा, उसके जन्म प्रमाणपत्र के साथ खोला जाता है। प्रति परिवार अधिकतम दो बालिकाएँ (जुड़वाँ या तीन बच्चों के एक साथ जन्म पर ही अधिक)।',
            bn: '10 বছরের কম বয়সী মেয়ের জন্য মা-বাবা বা অভিভাবক খোলেন, জন্ম সনদ সহ। প্রতি পরিবারে সর্বাধিক দুটি মেয়ে (যমজ বা তিন যমজ হলে বেশি)।',
            mr: '10 वर्षांखालील मुलीसाठी आई-वडील किंवा पालक तिच्या जन्म दाखल्यासह उघडतात. एका कुटुंबात जास्तीत जास्त दोन मुली (जुळ्या किंवा तिळ्या असल्यासच अधिक).',
            te: '10 ఏళ్ల లోపు బాలిక కోసం తల్లిదండ్రులు లేదా సంరక్షకుడు ఆమె జనన ధృవీకరణ పత్రంతో తెరుస్తారు. ఒక కుటుంబానికి గరిష్ఠంగా ఇద్దరు బాలికలు (కవలలు లేదా ముగ్గురు పిల్లలు ఒకే కాన్పులో పుడితే మాత్రమే ఎక్కువ).',
            ta: '10 வயதுக்குக் குறைவான சிறுமிக்கு, அவளது பிறப்புச் சான்றிதழுடன், பெற்றோர் அல்லது பாதுகாவலர் தொடங்குவர். ஒரு குடும்பத்துக்கு அதிகபட்சம் இரண்டு சிறுமிகள் (இரட்டையர் அல்லது மூவர் பிறப்புக்கு மட்டும் கூடுதல்).',
