            or: '10 ବର୍ଷରୁ କମ ବୟସର ଝିଅ ପାଇଁ ପିତାମାତା କିମ୍ବା ଅଭିଭାବକ ତା ଜନ୍ମ ପ୍ରମାଣପତ୍ର ସହ ଖୋଲନ୍ତି। ପରିବାର ପିଛା ସର୍ବାଧିକ ଦୁଇ ଝିଅ (ଯାଆଁଳା କିମ୍ବା ତିନି ଯାଆଁଳା ହେଲେ ହିଁ ଅଧିକ)।',
            pa: '10 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੀ ਕੁੜੀ ਲਈ ਮਾਤਾ-ਪਿਤਾ ਜਾਂ ਸਰਪ੍ਰਸਤ ਵੱਲੋਂ, ਉਸਦੇ ਜਨਮ ਸਰਟੀਫਿਕੇਟ ਨਾਲ ਖੋਲ੍ਹਿਆ ਜਾਂਦਾ ਹੈ। ਹਰ ਪਰਿਵਾਰ ਵਿੱਚ ਵੱਧ ਤੋਂ ਵੱਧ ਦੋ ਕੁੜੀਆਂ (ਜੁੜਵਾਂ ਜਾਂ ਤਿੰਨ ਬੱਚਿਆਂ ਦੀ ਹਾਲਤ ਵਿੱਚ ਹੀ ਵੱਧ)।',
