  String get taxNote => _t(
    'Tax = interest × your slab rate + 4% cess; estimate only. TDS of 10% (20% without PAN) is cut when post office interest in a year is above ₹50,000 (₹1,00,000 for senior citizens). Give Form 15G/15H if your income is below the taxable limit.',
    'ತೆರಿಗೆ = ಬಡ್ಡಿ × ನಿಮ್ಮ ಸ್ಲ್ಯಾಬ್ ದರ + 4% ಸೆಸ್; ಅಂದಾಜು ಮಾತ್ರ. ವರ್ಷದಲ್ಲಿ ಅಂಚೆ ಕಚೇರಿ ಬಡ್ಡಿ ₹50,000 (ಹಿರಿಯ ನಾಗರಿಕರಿಗೆ ₹1,00,000) ಮೀರಿದರೆ 10% TDS (PAN ಇಲ್ಲದಿದ್ದರೆ 20%) ಕಡಿತವಾಗುತ್ತದೆ. ಆದಾಯ ತೆರಿಗೆ ಮಿತಿಗಿಂತ ಕಡಿಮೆ ಇದ್ದರೆ ಫಾರ್ಮ್ 15G/15H ನೀಡಿ.',
    hi: 'टैक्स = ब्याज × आपकी स्लैब दर + 4% सेस; केवल अनुमान। साल में डाकघर का ब्याज ₹50,000 (वरिष्ठ नागरिकों के लिए ₹1,00,000) से अधिक होने पर 10% TDS (PAN न होने पर 20%) कटता है। अगर आपकी आय टैक्स-योग्य सीमा से कम है तो फ़ॉर्म 15G/15H दें।',
    bn: 'কর = সুদ × আপনার স্ল্যাব হার + 4% সেস; শুধু আনুমানিক। বছরে ডাকঘরের সুদ ₹50,000 (প্রবীণ নাগরিকদের জন্য ₹1,00,000)-এর বেশি হলে 10% TDS (PAN না থাকলে 20%) কাটা হয়। আপনার আয় করযোগ্য সীমার নিচে হলে ফর্ম 15G/15H জমা দিন।',
    mr: 'कर = व्याज × तुमचा स्लॅब दर + 4% सेस; फक्त अंदाज. वर्षभरात पोस्ट ऑफिसचे व्याज ₹50,000 (ज्येष्ठ नागरिकांसाठी ₹1,00,000) पेक्षा जास्त झाल्यास 10% TDS (PAN नसल्यास 20%) कापला जातो. तुमचे उत्पन्न करपात्र मर्यादेपेक्षा कमी असल्यास फॉर्म 15G/15H द्या.',
    te: 'పన్ను = వడ్డీ × మీ స్లాబ్ రేటు + 4% సెస్; అంచనా మాత్రమే. ఏడాదిలో పోస్టాఫీసు వడ్డీ ₹50,000 (సీనియర్ సిటిజన్లకు ₹1,00,000) దాటితే 10% TDS (PAN లేకపోతే 20%) కట్ అవుతుంది. మీ ఆదాయం పన్ను పరిమితి కంటే తక్కువ ఉంటే ఫారం 15G/15H ఇవ్వండి.',
    ta: 'வரி = வட்டி × உங்கள் அடுக்கு விகிதம் + 4% செஸ்; மதிப்பீடு மட்டுமே. ஒரு ஆண்டில் அஞ்சல் அலுவலக வட்டி ₹50,000 (மூத்த குடிமக்களுக்கு ₹1,00,000) தாண்டினால் 10% TDS (PAN இல்லையெனில் 20%) பிடிக்கப்படும். உங்கள் வருமானம் வரி வரம்புக்குக் கீழ் இருந்தால் படிவம் 15G/15H கொடுங்கள்.',
    gu: 'ટેક્સ = વ્યાજ × તમારો સ્લેબ દર + 4% સેસ; માત્ર અંદાજ. વર્ષમાં પોસ્ટ ઓફિસનું વ્યાજ ₹50,000 (વરિષ્ઠ નાગરિકો માટે ₹1,00,000) થી વધુ થાય તો 10% TDS (PAN ન હોય તો 20%) કપાય છે. તમારી આવક કરપાત્ર મર્યાદાથી ઓછી હોય તો ફોર્મ 15G/15H આપો.',
    ml: 'നികുതി = പലിശ × നിങ്ങളുടെ സ്ലാബ് നിരക്ക് + 4% സെസ്; ഏകദേശ കണക്ക് മാത്രം. ഒരു വർഷം പോസ്റ്റ് ഓഫീസ് പലിശ ₹50,000 (മുതിർന്ന പൗരന്മാർക്ക് ₹1,00,000) കവിഞ്ഞാൽ 10% TDS (PAN ഇല്ലെങ്കിൽ 20%) പിടിക്കും. നിങ്ങളുടെ വരുമാനം നികുതി പരിധിക്ക് താഴെയാണെങ്കിൽ ഫോം 15G/15H നൽകുക.',
    or: 'ଟିକସ = ସୁଧ × ଆପଣଙ୍କ ସ୍ଲାବ ହାର + 4% ସେସ; କେବଳ ଆନୁମାନିକ। ବର୍ଷରେ ଡାକଘର ସୁଧ ₹50,000 (ବରିଷ୍ଠ ନାଗରିକଙ୍କ ପାଇଁ ₹1,00,000) ରୁ ଅଧିକ ହେଲେ 10% TDS (PAN ନ ଥିଲେ 20%) କଟାଯାଏ। ଆପଣଙ୍କ ଆୟ ଟିକସଯୋଗ୍ୟ ସୀମାଠାରୁ କମ୍ ଥିଲେ ଫର୍ମ 15G/15H ଦିଅନ୍ତୁ।',
    pa: 'ਟੈਕਸ = ਵਿਆਜ × ਤੁਹਾਡੀ ਸਲੈਬ ਦਰ + 4% ਸੈੱਸ; ਸਿਰਫ਼ ਅੰਦਾਜ਼ਾ। ਸਾਲ ਵਿੱਚ ਡਾਕਘਰ ਦਾ ਵਿਆਜ ₹50,000 (ਸੀਨੀਅਰ ਨਾਗਰਿਕਾਂ ਲਈ ₹1,00,000) ਤੋਂ ਵੱਧ ਹੋਣ ’ਤੇ 10% TDS (PAN ਨਾ ਹੋਣ ’ਤੇ 20%) ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ। ਜੇ ਤੁਹਾਡੀ ਆਮਦਨ ਟੈਕਸਯੋਗ ਸੀਮਾ ਤੋਂ ਘੱਟ ਹੈ ਤਾਂ ਫ਼ਾਰਮ 15G/15H ਦਿਓ।',
  );

