  String get newRatesNote => _t(
    'Use this when the Government announces new rates before the app is updated. The next app update replaces them with the official table.',
    'ಆ್ಯಪ್ ಅಪ್‌ಡೇಟ್ ಬರುವ ಮೊದಲೇ ಸರ್ಕಾರ ಹೊಸ ದರ ಪ್ರಕಟಿಸಿದಾಗ ಇದನ್ನು ಬಳಸಿ. ಮುಂದಿನ ಆ್ಯಪ್ ಅಪ್‌ಡೇಟ್ ಅಧಿಕೃತ ಪಟ್ಟಿಯಿಂದ ಇವನ್ನು ಬದಲಿಸುತ್ತದೆ.',
    hi: 'जब ऐप अपडेट होने से पहले सरकार नई दरें घोषित करे, तब इसका उपयोग करें। अगला ऐप अपडेट इन्हें आधिकारिक तालिका से बदल देगा।',
    bn: 'অ্যাপ আপডেট হওয়ার আগেই সরকার নতুন হার ঘোষণা করলে এটি ব্যবহার করুন। পরের অ্যাপ আপডেট এগুলিকে সরকারি তালিকা দিয়ে বদলে দেবে।',
    mr: 'ॲप अपडेट होण्यापूर्वीच सरकारने नवीन दर जाहीर केल्यास याचा वापर करा. पुढील ॲप अपडेट हे दर अधिकृत तक्त्याने बदलेल.',
    te: 'యాప్ అప్‌డేట్ రాకముందే ప్రభుత్వం కొత్త రేట్లు ప్రకటించినప్పుడు దీన్ని ఉపయోగించండి. తదుపరి యాప్ అప్‌డేట్ వీటిని అధికారిక పట్టికతో భర్తీ చేస్తుంది.',
    ta: 'ஆப் புதுப்பிக்கப்படும் முன்பே அரசு புதிய விகிதங்களை அறிவித்தால் இதைப் பயன்படுத்துங்கள். அடுத்த ஆப் அப்டேட் இவற்றை அதிகாரப்பூர்வ அட்டவணையால் மாற்றும்.',
    gu: 'એપ અપડેટ થાય તે પહેલાં સરકાર નવા દરો જાહેર કરે ત્યારે આનો ઉપયોગ કરો. આગામી એપ અપડેટ તેમને સત્તાવાર કોષ્ટકથી બદલી દેશે.',
    ml: 'ആപ്പ് അപ്ഡേറ്റ് വരുന്നതിന് മുമ്പ് സർക്കാർ പുതിയ നിരക്കുകൾ പ്രഖ്യാപിച്ചാൽ ഇത് ഉപയോഗിക്കുക. അടുത്ത ആപ്പ് അപ്ഡേറ്റ് ഇവയെ ഔദ്യോഗിക പട്ടിക കൊണ്ട് മാറ്റും.',
    or: 'ଆପ୍ ଅପଡେଟ୍ ହେବା ପୂର୍ବରୁ ସରକାର ନୂଆ ହାର ଘୋଷଣା କଲେ ଏହା ବ୍ୟବହାର କରନ୍ତୁ। ପରବର୍ତ୍ତୀ ଆପ୍ ଅପଡେଟ୍ ଏଗୁଡ଼ିକୁ ସରକାରୀ ତାଲିକା ସହ ବଦଳାଇଦେବ।',
    pa: 'ਜਦੋਂ ਐਪ ਅੱਪਡੇਟ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਸਰਕਾਰ ਨਵੀਆਂ ਦਰਾਂ ਐਲਾਨੇ, ਤਾਂ ਇਸਦੀ ਵਰਤੋਂ ਕਰੋ। ਅਗਲੀ ਐਪ ਅੱਪਡੇਟ ਇਨ੍ਹਾਂ ਨੂੰ ਸਰਕਾਰੀ ਸੂਚੀ ਨਾਲ ਬਦਲ ਦੇਵੇਗੀ।',
  );
