    ml: 'പിഒ കാൽക്കുലേറ്റർ: 11 ഇന്ത്യൻ ഭാഷകളിൽ ഓഫ്‌ലൈൻ പോസ്റ്റ് ഓഫീസ് പലിശ കാൽക്കുലേറ്റർ. ഡൗൺലോഡ്: $url',
    or: 'ପିଓ କାଲକୁଲେଟର: 11ଟି ଭାରତୀୟ ଭାଷାରେ ଅଫଲାଇନ ଡାକଘର ସୁଧ କାଲକୁଲେଟର। ଡାଉନଲୋଡ: $url',
    pa: 'ਪੀਓ ਕੈਲਕੁਲੇਟਰ: 11 ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਆਫ਼ਲਾਈਨ ਡਾਕਘਰ ਵਿਆਜ ਕੈਲਕੁਲੇਟਰ। ਡਾਊਨਲੋਡ: $url',
