  String get privacyText => _t(
    'PO Calculator works fully offline. It has no internet permission, collects no data and shares nothing. Saved accounts stay only on this phone and are removed when you uninstall the app.',
    'ಪಿಒ ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಸಂಪೂರ್ಣ ಆಫ್‌ಲೈನ್. ಇಂಟರ್ನೆಟ್ ಅನುಮತಿ ಇಲ್ಲ, ಯಾವುದೇ ಮಾಹಿತಿ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ ಅಥವಾ ಹಂಚುವುದಿಲ್ಲ. ಉಳಿಸಿದ ಖಾತೆಗಳು ಈ ಫೋನ್‌ನಲ್ಲಿ ಮಾತ್ರ ಇರುತ್ತವೆ.',
    hi: 'पीओ कैलकुलेटर पूरी तरह ऑफ़लाइन काम करता है। इसमें इंटरनेट अनुमति नहीं है, यह कोई डेटा एकत्र नहीं करता और कुछ भी शेयर नहीं करता। सहेजे गए खाते केवल इसी फ़ोन पर रहते हैं और ऐप अनइंस्टॉल करने पर हट जाते हैं।',
    bn: 'পিও ক্যালকুলেটর সম্পূর্ণ অফলাইনে কাজ করে। এর ইন্টারনেট অনুমতি নেই, কোনো তথ্য সংগ্রহ করে না এবং কিছু শেয়ার করে না। সেভ করা অ্যাকাউন্ট শুধু এই ফোনেই থাকে এবং অ্যাপ আনইনস্টল করলে মুছে যায়।',
    mr: 'पीओ कॅल्क्युलेटर पूर्णपणे ऑफलाइन चालते. याला इंटरनेट परवानगी नाही, ते कोणताही डेटा गोळा करत नाही आणि काहीही शेअर करत नाही. जतन केलेली खाती फक्त याच फोनवर राहतात आणि ॲप अनइन्स्टॉल केल्यावर काढली जातात.',
    te: 'పిఓ కాలిక్యులేటర్ పూర్తిగా ఆఫ్‌లైన్‌లో పనిచేస్తుంది. దీనికి ఇంటర్నెట్ అనుమతి లేదు, ఎలాంటి డేటా సేకరించదు, ఏదీ షేర్ చేయదు. సేవ్ చేసిన ఖాతాలు ఈ ఫోన్‌లో మాత్రమే ఉంటాయి, యాప్ అన్‌ఇన్‌స్టాల్ చేస్తే తొలగిపోతాయి.',
    ta: 'பிஓ கால்குலேட்டர் முழுமையாக ஆஃப்லைனில் இயங்குகிறது. இதற்கு இணைய அனுமதி இல்லை, எந்தத் தரவையும் சேகரிப்பதில்லை, எதையும் பகிர்வதில்லை. சேமித்த கணக்குகள் இந்த ஃபோனில் மட்டுமே இருக்கும், செயலியை நீக்கும்போது அவையும் நீக்கப்படும்.',
    gu: 'પીઓ કેલ્ક્યુલેટર સંપૂર્ણપણે ઓફલાઇન ચાલે છે. તેને ઇન્ટરનેટની પરવાનગી નથી, તે કોઈ ડેટા એકત્ર કરતું નથી અને કંઈ શેર કરતું નથી. સાચવેલાં ખાતાં ફક્ત આ ફોનમાં જ રહે છે અને એપ અનઇન્સ્ટોલ કરવાથી દૂર થાય છે.',
    ml: 'പിഒ കാൽക്കുലേറ്റർ പൂർണ്ണമായും ഓഫ്‌ലൈനായി പ്രവർത്തിക്കുന്നു. ഇതിന് ഇന്റർനെറ്റ് അനുമതിയില്ല, ഒരു ഡാറ്റയും ശേഖരിക്കുന്നില്ല, ഒന്നും ഷെയർ ചെയ്യുന്നില്ല. സേവ് ചെയ്ത അക്കൗണ്ടുകൾ ഈ ഫോണിൽ മാത്രം സൂക്ഷിക്കും, ആപ്പ് അൺഇൻസ്റ്റാൾ ചെയ്യുമ്പോൾ നീക്കം ചെയ്യപ്പെടും.',
    or: 'ପିଓ କାଲକୁଲେଟର ସମ୍ପୂର୍ଣ୍ଣ ଅଫଲାଇନ କାମ କରେ। ଏହାର ଇଣ୍ଟରନେଟ ଅନୁମତି ନାହିଁ, କୌଣସି ତଥ୍ୟ ସଂଗ୍ରହ କରେ ନାହିଁ ଓ କିଛି ସେୟାର କରେ ନାହିଁ। ସେଭ ହୋଇଥିବା ଖାତା କେବଳ ଏହି ଫୋନରେ ରହେ ଓ ଆପ ଅନଇନଷ୍ଟଲ କଲେ ହଟିଯାଏ।',
    pa: 'ਪੀਓ ਕੈਲਕੁਲੇਟਰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਆਫ਼ਲਾਈਨ ਚੱਲਦਾ ਹੈ। ਇਸ ਕੋਲ ਇੰਟਰਨੈੱਟ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ, ਇਹ ਕੋਈ ਡਾਟਾ ਇਕੱਠਾ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਕੁਝ ਵੀ ਸਾਂਝਾ ਨਹੀਂ ਕਰਦਾ। ਸੇਵ ਕੀਤੇ ਖਾਤੇ ਸਿਰਫ਼ ਇਸ ਫ਼ੋਨ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਐਪ ਅਣਇੰਸਟਾਲ ਕਰਨ ’ਤੇ ਹਟ ਜਾਂਦੇ ਹਨ।',
  );
