  String years(int y) => lang == Lang.en && y == 1
      ? '1 year'
      : _t(
          '$y years',
          '$y ವರ್ಷ',
          hi: '$y वर्ष',
          bn: '$y বছর',
          mr: '$y वर्षे',
          te: '$y సంవత్సరాలు',
          ta: '$y ஆண்டுகள்',
          gu: '$y વર્ષ',
          ml: '$y വർഷം',
          or: '$y ବର୍ଷ',
          pa: '$y ਸਾਲ',
        );
  String tenureOf(Scheme s) => switch (s) {
    Scheme.sb => _t(
      'No fixed term',
      'ನಿಗದಿತ ಅವಧಿ ಇಲ್ಲ',
      hi: 'कोई निश्चित अवधि नहीं',
      bn: 'নির্দিষ্ট মেয়াদ নেই',
      mr: 'निश्चित मुदत नाही',
      te: 'నిర్ణీత వ్యవధి లేదు',
      ta: 'நிலையான காலம் இல்லை',
      gu: 'કોઈ નિશ્ચિત મુદત નથી',
      ml: 'നിശ്ചിത കാലാവധിയില്ല',
      or: 'ନିର୍ଦ୍ଦିଷ୍ଟ ଅବଧି ନାହିଁ',
      pa: 'ਕੋਈ ਨਿਸ਼ਚਿਤ ਮਿਆਦ ਨਹੀਂ',
    ),
    Scheme.kvp => months(115),
    Scheme.mssc => years(2),
    _ => years(s.tenureMonths ~/ 12),
  };
  String percentDone(int p) => _t(
    '$p% of term done',
    'ಅವಧಿಯ $p% ಮುಗಿದಿದೆ',
    hi: 'अवधि का $p% पूरा',
    bn: 'মেয়াদের $p% সম্পূর্ণ',
    mr: 'मुदतीपैकी $p% पूर्ण',
    te: 'వ్యవధిలో $p% పూర్తయింది',
    ta: 'காலத்தில் $p% முடிந்தது',
    gu: 'મુદતનો $p% પૂર્ણ',
    ml: 'കാലാവധിയുടെ $p% പൂർത്തിയായി',
    or: 'ଅବଧିର $p% ପୂରଣ',
    pa: 'ਮਿਆਦ ਦਾ $p% ਪੂਰਾ',
